// <auto-generated/>
using System;
using Sunplus.Accounting.Business.BootStrappers;
using Sunplus.Accounting.Business.Report.Racing;

public partial class Report_Racing_RacingExport : System.Web.UI.Page
{
    protected void Page_Load(object sender, EventArgs e)
    {
        if (Request["type"] != null)
        {
            var fDate = Request["fdate"] ?? DateTime.Now.ToShortDateString();
            var tDate = Request["tdate"] ?? DateTime.Now.ToShortDateString();
            var reportType = Request["reporttype"].ToString() ?? "groupdaily";

            if (Request["type"].ToLower().Equals("export"))
                ExportExcel(reportType, fDate, tDate);
            else if (Request["type"].ToLower().Equals("sendmail"))
                SendMail(reportType, fDate, tDate);
        } 
    }

    private void ExportExcel(string reportType, string fDate, string tDate) 
    {
        var racingReport = CommonBootStrapper.Locator.GetInstance<IReportRacing>();
        switch (reportType) 
        {
            case "groupdaily":
                racingReport.ExportToExcelWinLossRacingGroup(fDate, tDate);
                break;
            case "groupdailyfortote":
                racingReport.ExportToExcelWinLossRacingGroupForTote(fDate, tDate);
                break;
            case "reportbysite":
                racingReport.ExportToExcelWinlossRacingLicenseeDetails(fDate, Request["site"] ?? "12Bet", Request["reportporttitle"] ?? "Racing Daily Report");
                break;
            case "reportbysitept":
                racingReport.ExportToExcelWinlossRacingLicenseeDetailsPt(fDate, Request["site"] ?? "12Bet", Request["reportporttitle"] ?? "Racing Daily Report");
                break;
            case "racingdailyreportfortote":
                racingReport.ExportToExcelRacingDailyReportForTote(Request["title"], fDate);
                break;
            default:
                break;
        }
    }

    private void SendMail(string reportType, string fDate, string tDate) 
    {
        var racingReport = CommonBootStrapper.Locator.GetInstance<IReportRacing>();
        switch (reportType)
        {
            case "groupdaily":
                racingReport.SendMailWinLossRacingGroup(fDate, tDate);
                break;
            case "groupdailyfortote":
                racingReport.SendMailWinLossRacingGroupForTote(fDate, tDate);
                break;
            default:
                break;
        }
    }
}